import{_ as i,o as t,c as a,a3 as r}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Plugins ATLAS","description":"Documentation des extensions installables pour ATLAS.","frontmatter":{"title":"Plugins ATLAS","description":"Documentation des extensions installables pour ATLAS."},"headers":[],"relativePath":"fr/projects/atlas-plugins/index.md","filePath":"fr/projects/atlas-plugins/index.md","lastUpdated":1792862520000}'),s={name:"fr/projects/atlas-plugins/index.md"};function n(l,e,o,u,d,c){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="plugins-atlas" tabindex="-1">Plugins ATLAS <a class="header-anchor" href="#plugins-atlas" aria-label="Permalink to &quot;Plugins ATLAS&quot;">​</a></h1><h2 id="sauvegarder-et-restaurer-une-version-de-plugin" tabindex="-1">Sauvegarder et restaurer une version de plugin <a class="header-anchor" href="#sauvegarder-et-restaurer-une-version-de-plugin" aria-label="Permalink to &quot;Sauvegarder et restaurer une version de plugin&quot;">​</a></h2><p>Depuis ATLAS 0.1.304 :</p><ol><li>Sauvegarder d’abord HA/ATLAS et les données propres au plugin.</li><li>Importer un paquet de plugin existant dans le gestionnaire et vérifier les anciennes/nouvelles versions et capacités.</li><li>Sauvegarder et appliquer conserve une sauvegarde serveur avant remplacement. Vérifier explicitement toute compatibilité inconnue ; les paquets incompatibles restent bloqués.</li><li>Pour revenir, choisir Restaurer sur le plugin, vérifier la version sauvegardée et appliquer. La version installée est également sauvegardée.</li></ol><p>Les données du navigateur et leurs formats ne sont pas réinitialisés. Un ancien plugin doit accepter le format existant. Voir <a href="./developers/compatibility#préserver-et-restaurer-les-données">limites et emplacement</a>. L’interface est vérifiée isolément puis sur Pi 5 et Proxmox avec Icon Library, File Studio et Terminal ; autres plugins et migrations nécessitent des vérifications séparées.</p><p>Cette rubrique présente les extensions installables d&#39;ATLAS : format des dépôts, publication, mises à jour et pages consacrées à chaque plugin.</p><div class="warning custom-block"><p class="custom-block-title">État du développement</p><p>Les interfaces de plugins sont encore en cours d&#39;élaboration. La documentation décrit l&#39;état actuel d&#39;ATLAS et sera complétée à mesure que les contrats se stabiliseront.</p></div><h2 id="pour-commencer" tabindex="-1">Pour commencer <a class="header-anchor" href="#pour-commencer" aria-label="Permalink to &quot;Pour commencer&quot;">​</a></h2><ul><li><a href="./repository-format">Format du dépôt</a> : structure de <code>repository.json</code>, champs obligatoires, identifiant ATLAS et exemple.</li><li><a href="./plugin-template">Modèle de plugin</a> : utiliser le modèle, personnaliser un plugin, créer son paquet et le publier.</li><li><a href="./developers/">Développement de plugins</a> : structure, manifeste, cycle de vie Runtime et publication.</li><li><a href="./verified-plugins">Plugins vérifiés</a> : liste des plugins vérifiés et des nouvelles propositions qui restent à examiner.</li><li><a href="./homeassistant-card-editor">Home Assistant Card Editor</a> : premier plugin de référence officiel d&#39;ATLAS.</li><li><a href="./file-studio">ATLAS File Studio</a> : plugin indépendant pour les chemins Home Assistant autorisés.</li><li><a href="./icon-studio">ATLAS Icon Studio</a> : gérer, importer et enregistrer des jeux d’icônes pour Home Assistant.</li><li><a href="./icon-library">Bibliothèque d’icônes ATLAS</a> : parcourir les jeux d’icônes et copier leurs noms complets.</li><li><a href="./terminal">ATLAS Terminal</a> : terminal web authentifié avec couleurs ANSI, SSH facultatif, thèmes Oh My Posh et police Nerd Font servie par le serveur.</li><li><a href="./automation-extractor">ATLAS Automation Exporter / Editor</a> : analyse, sauvegarde de sécurité et export d&#39;automatisations Home Assistant.</li><li><a href="./demo-repository">Dépôt de démonstration</a> : dépôt public de test pour l&#39;Administration, le Hub et le parcours d&#39;installation.</li></ul><h2 id="objectif" tabindex="-1">Objectif <a class="header-anchor" href="#objectif" aria-label="Permalink to &quot;Objectif&quot;">​</a></h2><p>Les plugins ATLAS étendent la plateforme sans modifier directement ses paquets centraux. Ils peuvent fournir des outils liés à Home Assistant, des éditeurs de cartes, des outils de diagnostic, des moteurs de rendu, des thèmes, des fournisseurs ou, à terme, des extensions communautaires.</p><h2 id="cycle-de-vie" tabindex="-1">Cycle de vie <a class="header-anchor" href="#cycle-de-vie" aria-label="Permalink to &quot;Cycle de vie&quot;">​</a></h2><p>Un plugin doit pouvoir être installé, vérifié, activé, mis à jour et supprimé de manière traçable :</p><ol><li>Lire le manifeste.</li><li>Vérifier les dépendances.</li><li>Enregistrer le plugin.</li><li>Fournir des services, commandes ou interfaces.</li><li>Activer le plugin.</li><li>Signaler les diagnostics et l&#39;état.</li><li>Désactiver le plugin ou le supprimer proprement.</li></ol><h2 id="reference-technique-actuelle" tabindex="-1">Référence technique actuelle <a class="header-anchor" href="#reference-technique-actuelle" aria-label="Permalink to &quot;Référence technique actuelle&quot;">​</a></h2><p>L&#39;adaptateur Runtime constitue le point d&#39;entrée actuel. <code>createRuntimeModuleFromPlugin()</code> convertit un <code>RuntimePlugin</code> en module Runtime ATLAS. <code>RuntimePluginCatalog</code> permet la découverte ; l&#39;Administration affiche les plugins, compare leurs versions et prépare les installations locales.</p><p>Le Hub suit une règle de démarrage simple : sans plugin installé, il renvoie vers l&#39;Administration ; avec un seul plugin actif, il ouvre directement celui-ci ; avec deux plugins actifs ou plus, il affiche la page de sélection. Les plugins planifiés ou désactivés peuvent être affichés, mais ne démarrent pas automatiquement.</p><p>Le Hub peut aussi préparer des entrées de barre latérale Home Assistant. La fenêtre affiche dynamiquement le nom, l&#39;URL, la version, l&#39;état et l&#39;icône proposée, puis copie l&#39;URL seule ou un bloc <code>panel_iframe</code> prêt à utiliser dans <code>configuration.yaml</code>. L’URL seule peut servir à un tableau de bord Home Assistant de type <code>Webpage</code>. Les listes de capacités et les URL restent repliées par défaut afin de garder le Hub compact.</p><p>En mode App/Add-on, Card Editor, Administration et les ressources locales des plugins sont servies par les routes de l&#39;application ATLAS. Les chemins de base Home Assistant Ingress sont ainsi conservés dans le Hub et les liens de barre latérale ; les autres clients réseau n’ont pas besoin d’accéder directement aux ports de développement.</p><h3 id="preference-de-langue-partagee" tabindex="-1">Préférence de langue partagée <a class="header-anchor" href="#preference-de-langue-partagee" aria-label="Permalink to &quot;Préférence de langue partagée&quot;">​</a></h3><p>L&#39;Administration et le Hub des plugins prennent en charge l&#39;allemand, l&#39;anglais et le français. La langue choisie dans l&#39;une des interfaces est mémorisée et utilisée dans l&#39;autre, même si elles fonctionnent sur des ports différents. Un paramètre <code>language</code> explicite dans l&#39;URL d&#39;un plugin reste prioritaire pour la visite en cours.</p><p>Pour File Studio, le Hub prépare <code>/plugin-assets/file-studio/index.html</code> sur le port de l’application ATLAS ou à travers l’adresse Ingress/Webpage, même si les anciennes données du plugin ne contiennent pas encore d’URL.</p><p>Les nouveaux plugins locaux reçoivent une URL de lancement automatique si leur dossier contient <code>index.html</code> et que le manifeste ne définit pas <code>entry</code>. ATLAS publie alors <code>/plugin-assets/&lt;dossier-du-plugin&gt;/index.html</code>.</p><h2 id="regles-de-publication" tabindex="-1">Règles de publication <a class="header-anchor" href="#regles-de-publication" aria-label="Permalink to &quot;Règles de publication&quot;">​</a></h2><p>Un plugin publiable doit avoir un nom clair, une version explicite, des dépendances documentées, des données de démonstration ou de repli sûres, des artefacts de build traçables et des indications pour ATLAS, Home Assistant ou HACS.</p><h2 id="automation-exporter-editor" tabindex="-1">Automation Exporter / Editor <a class="header-anchor" href="#automation-exporter-editor" aria-label="Permalink to &quot;Automation Exporter / Editor&quot;">​</a></h2><p>ATLAS Automation Exporter / Editor ajoute des outils pour détecter les automatisations, afficher leurs dépendances, créer une sauvegarde de sécurité lors de la lecture et exporter une version d&#39;archive qui conserve l&#39;<code>id</code>, ainsi qu&#39;une version d&#39;import nettoyée sans <code>id</code> pour l&#39;éditeur YAML de Home Assistant.</p>',27)])])}const g=i(s,[["render",n]]);export{m as __pageData,g as default};
